protected.btn_AddNhapTuSanXuat.OnSelect:
=Set(
    varProductionReceiptDetail,
    {}
);
Reset(dp_ReceiptDate);
Reset(cmb_Shift);
Reset(cmb_ProductType);
Navigate(
    scrNhapTuSanXuatForm,
    ScreenTransition.CoverRight
)

protected.lbl_StatusCode.Text:
=With(
    {
        statusItem: LookUp(
            col_WorkflowStatus,
            StatusCode = ThisItem.StatusCode
        )
    },
    If(
        scrNhapTuSanXuat.Size = 1,
        "Trạng thái : ",
        ""
    ) &
    Coalesce(
        If(
            _defaultLanguage.Code = "EN",
            statusItem.StatusNameEN,
            statusItem.StatusNameVI
        ),
        ThisItem.StatusCode
    )
)

protected.btn_ViewNhapTuSanXuat.OnSelect:
=// Lưu phiếu được chọn
Set(varProductionReceiptDetail, ThisItem);


// Chuyển sang màn hình form chi tiết phiếu nhập
Navigate(scrNhapTuSanXuatForm, ScreenTransition.CoverRight)

protected.btn_DeleteNhapTuSanXuat.OnSelect:
=If(
    Confirm(
        "Bạn có chắc muốn xóa bản ghi này không?",
        {
            Title: "Xác nhận xóa",
            Subtitle: "Hành động này không thể hoàn tác.",
            ConfirmButton: "Xóa",
            CancelButton: "Hủy"
        }
    ),
    UpdateContext({varShowPopupProcessing:true});
    IfError(
        Clear(col_DetailToDelete);
        ClearCollect(
            col_DetailToDelete,
            Filter(
                'QLK List Production Receipt Details',
                ReceiptID = ThisItem.ID
            )
        );
        Remove('QLK List Production Receipt Details', col_DetailToDelete);
        Remove('QLK List Production Receipts', ThisItem);
        ,
        UpdateContext({varShowPopupProcessing:false});
        Notify("Xóa không thành công", NotificationType.Error,2000);
        ,
        UpdateContext({varShowPopupProcessing:false});
        Notify("Xóa thành công", NotificationType.Success,2000)
    )
)

